const LOGO='data:image/webp;base64,';
const ICON={gift:'<rect x="3" y="9" width="18" height="12" rx="2"/><path d="M12 9v12M3 13h18M12 9c-4-1-6-4-4-6 2-2 4 1 4 6Zm0 0c4-1 6-4 4-6-2-2-4 1-4 6Z"/>',link:'<path d="M10 13a5 5 0 0 0 7 .2l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7-.2l-3 3a5 5 0 0 0 7 7l1.7-1.7"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',external:'<path d="M14 4h6v6M20 4l-9 9"/><path d="M20 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5"/>',home:'<path d="M3 10.5 12 3l9 7.5V21H3z"/><path d="M9 21v-7h6v7"/>',clipboard:'<rect x="5" y="5" width="14" height="16" rx="2"/><path d="M9 5V3h6v2M9 11h6M9 15h4"/>',history:'<path d="M3 12a9 9 0 1 0 4-7.5"/><path d="M3 4v5h5M12 7v5l4 2"/>',wallet:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 9V5a2 2 0 0 1 2-2h13M16 14h6v4h-6a2 2 0 0 1 0-4Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 2 1 2h2l1-2 3 2-.5 2.4 1.5 1.5L20.5 7 22 10l-2 1v2l2 1-1.5 3-2.5-.5-1.5 1.5L17 20.5 14 22l-1-2h-2l-1 2-3-1.5.5-2.5L6 16.5 3.5 17 2 14l2-1v-2l-2-1 1.5-3 2.5.5L7.5 6 7 3.5z"/>',chart:'<path d="M4 20V10M10 20V4M16 20v-8M22 20V7"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',users:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M17 5a4 4 0 0 1 0 7M18 15a6 6 0 0 1 4 6"/>',shield:'<path d="M12 2 21 6v6c0 6-4 9-9 10-5-1-9-4-9-10V6z"/><path d="m8 12 3 3 5-6"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',coins:'<circle cx="8" cy="9" r="6"/><path d="M8 6v6M5.5 8h5M13 8a6 6 0 1 1-2 11"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>'};
ICON.eye='<path d="M2 12s3.7-6.5 10-6.5S22 12 22 12s-3.7 6.5-10 6.5S2 12 2 12Z"/><circle cx="12" cy="12" r="2.8"/>';
ICON.eyeOff='<path d="M3 3l18 18M9.7 5.8a11 11 0 0 1 2.3-.3c6.3 0 10 6.5 10 6.5a14.9 14.9 0 0 1-3.1 3.7M6.1 7.8C3.5 9.5 2 12 2 12s3.7 6.5 10 6.5c1.4 0 2.7-.3 3.8-.8M10.6 10.6a2 2 0 0 0 2.8 2.8"/>';
ICON.lock='<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>';
ICON.info='<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7.2v.5"/>';

// SanzuFreelance — frontend anggota LIVE.
// Tampilan mengikuti file demo anggota (shell, hero, room, metrik, tabel,
// modal, toast, dan class CSS demo di style.css). Yang diganti dari demo:
// data hardcode -> endpoint /api yang sudah ada; tombol switcher Anggota/
// Admin dihapus; tombol penarikan memanggil POST withdraw NYATA (bukan
// pratinjau demo); label simulasi demo dan teks simulasi dihapus.
// Backend (api/index.js, lib/*) TIDAK diubah oleh file ini.
const $ = (s, el = document) => el.querySelector(s);
const money = (n) => "Rp " + Number(n || 0).toLocaleString("id-ID");
const escA = (s) => String(s ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
const fmtDate = (iso) => {
  if (!iso) return "-";
  try {
    return new Intl.DateTimeFormat("id-ID", { timeZone: "Asia/Jakarta", day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date(iso)).replace(",", " •") + " WIB";
  } catch { return String(iso); }
};
const ico = (name) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" aria-hidden="true">${ICON[name] || ICON.home}</svg>`;
const pill = (s) => {
  const k = { Diterima: "green", Good: "green", Captcha: "amber", Menunggu: "amber", Diperiksa: "blue", Diproses: "purple", Ditolak: "red", "Disabled / Verify": "red", "Menunggu Transfer": "amber", Selesai: "green", "Menunggu Konfirmasi": "amber", Dibayarkan: "green" }[s] || "blue";
  return `<span class="badge ${k}">${escA(s)}</span>`;
};
const metric = (label, value, icon, small = "") => `<div class="metric"><div class="m-top"><span class="m-label">${label}</span><span class="icon-bg">${ico(icon)}</span></div><div class="m-val">${value}</div>${small ? `<div class="m-small">${small}</div>` : ""}</div>`;
const infoStep = (num, icon, title, desc, kind) => `<div class="info-step"><div class="step-rail"><span class="step-dot ${kind === "violet" ? "violet" : kind === "mint" ? "mint" : ""}"></span></div><div class="step-card"><span class="step-icon ${kind === "violet" ? "violet" : kind === "mint" ? "mint" : ""}">${ico(icon)}</span><div class="step-copy"><strong>${title}</strong><p>${desc}</p></div><span class="step-number ${kind === "violet" ? "violet" : kind === "mint" ? "mint" : ""}">${num}</span></div></div>`;
async function api(action, opts = {}) {
  const r = await fetch(`/api?action=${action}`, { method: opts.method || "GET", headers: { "Content-Type": "application/json" }, body: opts.body ? JSON.stringify(opts.body) : undefined });
  let data = {};
  try { data = await r.json(); } catch {}
  if (!r.ok) throw new Error(data.error || `Gagal memuat (${r.status})`);
  return data;
}
function showToast(msg) {
  const root = $("#toast-root");
  root.innerHTML = `<div class="toast">${escA(msg)}</div>`;
  setTimeout(() => { if (root.firstChild) root.innerHTML = ""; }, 4200);
}
function closeModal() { $("#modal-root").innerHTML = ""; }
function feeFor(amount, method, s) {
  if (amount < 50000) return 0;
  if (amount <= 100000) return method === "SeaBank" ? s.fee_seabank_tier1 : s.fee_dana_tier1;
  return method === "SeaBank" ? s.fee_seabank_tier2 : s.fee_dana_tier2;
}

let tab = "home", me = null, settings = null, room = "Good", showSubmissions = true;
let subsCache = [], notifsCache = [];
const NAV = [["home", "Beranda", "home"], ["submit", "Pengajuan", "clipboard"], ["history", "Riwayat", "history"], ["referral", "Referral", "gift"], ["profile", "Profil", "user"]];
function stateLabel() {
  if (!me) return "";
  return me.user.state === "Menunggu" ? "Menunggu persetujuan" : me.user.state === "Aktif" ? "Anggota aktif" : "Akun nonaktif";
}
function renderShell() {
  $("#sidebar").innerHTML = `<div class="brand"><img class="brand-mark" src="${LOGO}" alt="Logo SanzuFreelance"><div><div class="brand-title">SanzuFreelance</div><div class="brand-sub">DIGITAL WORKSPACE</div></div></div><div class="side-label">MENU UTAMA</div>${NAV.map(([key, label, icon]) => `<button class="nav-item ${tab === key ? "active" : ""}" data-tab="${key}">${ico(icon)}<span>${label}</span></button>`).join("")}<div class="side-bottom"><div class="profile-chip"><div class="avatar avatar-default">${ico("user")}</div><div><div style="font-size:12px;font-weight:800">${escA(me ? me.user.display_name : "")}</div><div class="tiny-muted">${stateLabel()}</div></div></div><button class="btn btn-outline" id="btn-logout" style="width:100%;margin-top:12px;justify-content:center">Keluar</button></div>`;
  $("#mobile-brand").innerHTML = `<img src="${LOGO}" alt="Logo Sanzu"><strong>SanzuFreelance</strong>`;
  $("#mobile-nav").innerHTML = NAV.map(([key, label, icon]) => `<button class="${tab === key ? "active" : ""}" data-tab="${key}">${ico(icon)}<span>${label}</span></button>`).join("");
  $("#btn-bell").innerHTML = ico("bell");
  document.querySelectorAll("[data-tab]").forEach((b) => b.addEventListener("click", () => { tab = b.dataset.tab; render(); }));
  $("#top-heading").textContent = NAV.find((x) => x[0] === tab)?.[1] || "Beranda";
  const lo = $("#btn-logout");
  if (lo) lo.addEventListener("click", async () => { try { await api("logout", { method: "POST", body: {} }); } catch {} location.reload(); });
  $("#btn-bell").onclick = openInbox; // onclick (bukan addEventListener) agar tidak menumpuk tiap render
}
function setTab(t) { tab = t; render(); }
function setRoom(r) { room = r; render(); }
function toggleSubmissions(v) { showSubmissions = v; render(); }
function countItems(el) {
  const list = el.value.split(/[\s,;]+/).map((x) => x.trim()).filter(Boolean);
  const c = $("#entry-count");
  if (c) c.textContent = `Terbaca ${list.length} entri · Maksimal 50 per pengajuan · Batas harian ${settings ? settings.daily_limit : 50} · Hanya @gmail.com`;
}
function inboxHTML(items) {
  if (!items.length) return `<div class="profile-empty">Belum ada pemberitahuan. Perubahan status dari admin akan muncul di sini.</div>`;
  return items.map((n) => `<div class="profile-inbox-row"><span class="profile-inbox-icon">${ico(n.type === "store" ? "info" : "bell")}</span><div><strong>${escA(n.title)}</strong><p>${escA(n.body)}</p><small>${fmtDate(n.created_at)}</small></div></div>`).join("");
}
async function openInbox() {
  try { notifsCache = (await api("notifications")).notifications; } catch (e) { showToast(e.message); return; }
  $("#modal-root").innerHTML = `<div class="modal-overlay" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:530px"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px"><h2>Pemberitahuan</h2><button class="ghost-icon" aria-label="Tutup" onclick="closeModal()">${ico("close")}</button></div><p class="profile-help">Notifikasi dalam website dari admin.</p><div class="profile-inbox">${inboxHTML(notifsCache)}</div><div class="modal-actions"><button class="btn btn-primary" onclick="closeModal();setTab('profile')">Pengaturan Notifikasi</button></div></div></div>`;
}
function roomsHTML() {
  return `<section class="room-section"><div class="section-head"><div><h2>Room Pengajuan</h2><p>Kategori dan tarif yang berlaku saat ini</p></div></div><div class="rooms"><div class="room"><div class="room-top"><h3>Good</h3>${pill("Good")}</div><div class="room-price">${money(settings.rate_good)} <small>/ diterima</small></div><p class="room-desc">Catatan: Setelah mengisi email dan di klik berikutnya langsung mengarah ke kolom password.</p></div><div class="room captcha"><div class="room-top"><h3>Captcha</h3>${pill("Captcha")}</div><div class="room-price">${money(settings.rate_captcha)} <small>/ diterima</small></div><p class="room-desc">Catatan: Setelah mengisi email dan di klik berikutnya terkena “verifikasi anda bukan robot.”</p></div></div></section>`;
}
function rowTableHTML(rows) {
  return `<div class="table-wrap"><table><thead><tr><th>ID</th><th>Kategori</th><th>Status</th><th>Nominal</th></tr></thead><tbody>${rows.map((s) => `<tr><td class="table-id">${escA(s.id)}</td><td>${pill(s.quality)}</td><td>${pill(s.stage)}</td><td>${s.stage === "Diterima" ? money(s.paid_rate) : "—"}</td></tr>`).join("") || `<tr><td colspan="4" class="muted">Belum ada pengajuan.</td></tr>`}</tbody></table></div>`;
}
function recentBodyHTML() {
  if (!showSubmissions) return `<div class="hidden-recent" aria-live="polite"><span class="hidden-lock">${ico("lock")}</span><strong>Status: Disembunyikan</strong><p>Klik Tampilkan untuk melihat pengajuan terakhir.</p></div>`;
  const rows = subsCache.slice(0, 6);
  return `<div class="recent-scroller">${rowTableHTML(subsCache)}</div><div class="mobile-recent-list">${rows.map((s) => `<div class="recent-item"><div class="recent-row"><strong>${escA(s.id)}</strong><span>${pill(s.stage)}</span></div><div class="recent-row details"><span>${pill(s.quality)}</span><strong>${s.stage === "Diterima" ? money(s.paid_rate) : "Belum ada nominal"}</strong></div></div>`).join("")}</div><div class="recent-footer"><button class="inline-action" onclick="setTab('history')">Lihat Semua Pengajuan →</button></div>`;
}

// ---- Penarikan: NYATA, bukan pratinjau demo ----
// Demo hanya menampilkan pratinjau dan tidak pernah menyimpan apa pun —
// itulah sebabnya penarikan anggota tidak pernah muncul di admin.
// Versi live ini memanggil POST /api?action=withdraw dan menampilkan
// ID + nominal + fee + bersih dari respons server. Bila gagal, pesan
// error dari server ditampilkan di modal (bukan disembunyikan).
function withdrawModal() {
  const active = ["DANA", "SeaBank"].filter((m) => settings.withdraw_enabled && (m === "DANA" ? settings.withdraw_dana : settings.withdraw_seabank));
  const bal = me.balance;
  $("#modal-root").innerHTML = `<div class="modal-overlay" onclick="if(event.target===this)closeModal()"><div class="modal"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Ajukan Penarikan</h2><button class="ghost-icon" aria-label="Tutup" onclick="closeModal()">${ico("close")}</button></div><p>Saldo tersedia <strong style="color:white">${money(bal)}</strong>. Satu penarikan aktif diperbolehkan dalam satu waktu.</p>${active.length ? `<div class="form-field"><label>Metode penarikan</label><select class="field" id="withdraw-method" onchange="updateWithdrawPreview()">${active.map((x) => `<option ${x === me.user.payment_method ? "selected" : ""}>${x}</option>`).join("")}</select></div><div class="profile-notice" id="withdraw-destination">Tujuan penarikan mengikuti nomor yang disimpan pada Profil. Jika belum diisi, atur profil terlebih dahulu.</div><div class="form-field"><label>Nominal penarikan (Rp)</label><input class="field" id="withdraw-amount" type="number" min="1" max="${bal}" placeholder="Contoh: 40000" oninput="updateWithdrawPreview()"><button class="inline-action" style="margin-top:9px" onclick="document.getElementById('withdraw-amount').value=${bal};updateWithdrawPreview()">Tarik Semua: ${money(bal)}</button></div><div id="withdraw-preview" class="note">Pilih metode dan nominal untuk melihat perkiraan biaya admin.</div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary" id="btn-wd-submit">Ajukan Penarikan</button></div>` : `<div class="note">${settings.withdraw_enabled ? "Metode penarikan sedang tidak tersedia. Silakan hubungi admin." : "Penarikan sedang dinonaktifkan oleh admin. Silakan coba kembali setelah layanan dibuka."}</div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Tutup</button></div>`}<p class="help">Penarikan ini tercatat di server dan langsung muncul di daftar Penarikan admin. Transfer dilakukan manual oleh admin, lalu admin menandai Selesai.</p></div></div>`;
  updateWithdrawPreview();
  const btn = $("#btn-wd-submit");
  if (btn) btn.addEventListener("click", submitWithdrawal);
}
function updateWithdrawPreview() {
  const el = $("#withdraw-preview");
  if (!el) return;
  const methodEl = $("#withdraw-method");
  if (!methodEl) return;
  const method = methodEl.value;
  const amt = Number($("#withdraw-amount").value || 0);
  const dest = $("#withdraw-destination");
  if (dest) {
    if (method === me.user.payment_method && me.user.payment_number) dest.textContent = `Tujuan: ${method} · ${me.user.payment_number}`;
    else dest.textContent = `Nomor untuk metode ${method} belum tersimpan sebagai metode utama. Pilih metode yang tersimpan di Profil, atau ubah dulu di Profil.`;
  }
  if (!Number.isSafeInteger(amt) || amt < 1 || amt > me.balance) { el.textContent = `Masukkan nominal antara Rp1 sampai ${money(me.balance)}.`; return; }
  const fee = feeFor(amt, method, settings);
  el.textContent = `Metode ${method} • Nominal ${money(amt)} • Biaya admin ${money(fee)} • Bersih diterima ${money(amt - fee)}`;
}
async function submitWithdrawal() {
  const btn = $("#btn-wd-submit");
  const method = $("#withdraw-method").value;
  const amount = Number($("#withdraw-amount").value || 0);
  const preview = $("#withdraw-preview");
  if (btn) { btn.disabled = true; btn.textContent = "Mengirim…"; }
  try {
    const r = await api("withdraw", { method: "POST", body: { method, amount } });
    const w = r.withdrawal;
    closeModal();
    showToast(`Penarikan ${w.id} diajukan: nominal ${money(w.amount)}, biaya ${money(w.fee)}, bersih ${money(w.net)}.`);
    await refreshMe();
    render();
  } catch (e) {
    if (preview) { preview.textContent = e.message; preview.style.borderColor = "#6f3546"; }
    showToast(e.message);
    if (btn) { btn.disabled = false; btn.textContent = "Ajukan Penarikan"; }
  }
}
async function refreshMe() { me = await api("me"); }

async function render() {
  renderShell();
  const page = $("#page");
  try {
    if (tab === "home") {
      subsCache = (await api("submissions")).submissions;
      const latest = subsCache.slice(0, 5);
      const timeline = [];
      const acc = subsCache.find((s) => s.stage === "Diterima");
      if (acc) timeline.push(`<div class="activity"><div class="activity-circle success">${ico("check")}</div><div class="activity-content"><strong>${escA(acc.id)} berhasil diterima</strong><p>Kategori ${escA(acc.quality)} • ${fmtDate(acc.created_at)} • Penghasilan ${money(acc.paid_rate)}</p></div></div>`);
      const prog = subsCache.find((s) => ["Menunggu", "Diperiksa", "Diproses"].includes(s.stage));
      if (prog) timeline.push(`<div class="activity"><div class="activity-circle">${ico("history")}</div><div class="activity-content"><strong>${escA(prog.id)} ${escA(prog.stage)}</strong><p>Kategori ${escA(prog.quality)} • ${fmtDate(prog.created_at)}</p></div></div>`);
      const wait = subsCache.find((s) => s.stage === "Menunggu");
      if (wait && (!prog || prog.id !== wait.id)) timeline.push(`<div class="activity"><div class="activity-circle amber-circle">${ico("clock")}</div><div class="activity-content"><strong>${escA(wait.id)} menunggu pemeriksaan</strong><p>Kategori ${escA(wait.quality)} • ${fmtDate(wait.created_at)}</p></div></div>`);
      page.innerHTML = `
        ${me.user.state !== "Aktif" ? `<div class="profile-notice" role="status" style="margin:0 0 14px;color:#ffcf9e">${me.user.state === "Menunggu" ? "Akunmu masih menunggu persetujuan admin. Setor dan penarikan dibuka setelah admin menyetujui akunmu." : "Akunmu dinonaktifkan admin. Setor dan penarikan ditutup."}</div>` : ""}
        ${!settings.store_open ? `<div class="profile-notice" role="status" style="margin:0 0 14px;color:#ffcf9e">Setoran sedang ditutup admin. Kamu belum bisa mengirim pengajuan baru.</div>` : ""}
        <section class="hero balance-hero"><div class="balance-details"><div class="intro">SALDO TERSEDIA</div><div class="money">${money(me.balance)}</div><div class="hero-actions"><button class="btn btn-primary" id="btn-hero-wd">${ico("wallet")} Tarik Saldo</button><button class="btn btn-secondary" id="btn-hero-submit">${ico("arrow")} Buat Pengajuan</button></div></div><div class="balance-facets" aria-hidden="true"><span class="facet facet-one"></span><span class="facet facet-two"></span><span class="facet facet-three"></span><span class="facet facet-four"></span></div></section>
        ${roomsHTML()}
        <h2 class="earnings-heading">Total pengajuan dan penjualan yang berhasil diterima dari kategori Good maupun Captcha</h2>
        <div class="metrics member-metrics">${metric("Total Pengajuan", String(me.summary.total), "clipboard")}${metric("Diterima", String(me.summary.accepted), "check")}${metric("Dalam Proses", String(me.summary.in_process), "clock")}${metric("Ditolak", String(me.summary.rejected), "shield")}</div>
        <section class="home-activity"><div class="section-head activity-head"><div><h2>Pengajuan Terakhir</h2><p>Pantau setiap perkembangan tanpa menebak status</p></div><div class="visibility-actions" role="group" aria-label="Visibilitas pengajuan terakhir"><button class="visibility-btn ${showSubmissions ? "on" : ""}" onclick="toggleSubmissions(true)" aria-pressed="${showSubmissions}">${ico("eye")} Tampilkan</button><button class="visibility-btn ${!showSubmissions ? "on" : ""}" onclick="toggleSubmissions(false)" aria-pressed="${!showSubmissions}">${ico("eyeOff")} Sembunyikan</button></div></div><div class="panel recent-panel"><div id="recent-display">${recentBodyHTML()}</div></div>
        <div class="panel timeline-panel"><div class="panel-head"><h3>Linimasa Pemeriksaan</h3><button class="inline-action" onclick="setTab('history')">Lihat Semua →</button></div>${timeline.length ? timeline.join("") : `<p class="muted">Belum ada aktivitas pemeriksaan.</p>`}</div></section>`;
      $("#btn-hero-wd").addEventListener("click", withdrawModal);
      $("#btn-hero-submit").addEventListener("click", () => setTab("submit"));
    } else if (tab === "submit") {
      page.innerHTML = `<h1 class="wide-title">Buat Pengajuan</h1><p class="page-sub submit-subtitle">Pilih room sesuai kondisi stokmu, lalu masukkan daftar pengajuan di bawah ini.</p>${!settings.store_open ? `<div class="profile-notice" role="status" style="margin:0 0 14px;color:#ffcf9e">Setoran sedang ditutup admin. Kamu belum bisa mengirim pengajuan baru.</div>` : ""}<div class="submit-stack"><div class="panel submit-panel"><div class="panel-head"><h3>Detail Pengajuan</h3><span class="badge purple">Batas ${settings.daily_limit} / hari</span></div><div class="form-field"><label>Stor stokmu</label><div class="pills room-choice"><button class="${room === "Good" ? "active" : ""}" onclick="setRoom('Good')">Room Good</button><button class="${room === "Captcha" ? "active" : ""}" onclick="setRoom('Captcha')">Room Captcha</button></div><div class="help">Harap stor dengan opsi yang valid, sesuai kondisi akun stokmu tersebut.</div></div><div class="form-field"><label for="bulk-entries">Storkan stokmu di bawah sini.</label><textarea id="bulk-entries" class="field bulk-entries" placeholder="contoh1@gmail.com&#10;contoh2@gmail.com&#10;contoh3@gmail.com" oninput="countItems(this)" aria-describedby="entry-count entry-error"></textarea><div class="help" id="entry-count">Terbaca 0 entri · Maksimal 50 per pengajuan · Batas harian ${settings.daily_limit} · Hanya @gmail.com</div><div class="gmail-validation" id="entry-error" role="alert" aria-live="polite" hidden></div></div><div class="form-field"><label for="review-notes">Catatan untuk admin</label><textarea id="review-notes" rows="2" class="field note-field" placeholder="isi"></textarea></div><button class="btn btn-primary submit-btn" id="btn-send-submit" ${!settings.store_open ? "disabled" : ""}>${ico("clipboard")} Kirim</button></div>
      <div class="panel info-panel"><div class="info-heading"><span class="info-title-icon">${ico("info")}</span><h3>Informasi Pengajuan</h3></div><div class="steps-wrapper">${infoStep("01", "clock", "Menunggu", "Masuk antrean pemeriksaan admin.", "blue")}${infoStep("02", "search", "Sedang diperiksa", "Hasil klasifikasi bisa Good, Captcha, atau Disabled / Verify.", "violet")}${infoStep("03", "settings", "Diproses lebih lanjut", "Pekerjaan belum menghasilkan saldo.", "mint")}${infoStep("04", "check", "Diterima / Ditolak", "Saldo baru bertambah jika diterima secara final.", "violet")}</div><div class="notice safe-note telegram-note"><span class="warning-ico">${ico("info")}</span><span>harap masuk ke grub telegram komunitas admin dibawah ya, jika kamu punya telegram. supaya dapat menerima informasi update apapun dari admin.</span></div>${settings.telegram_url ? `<a class="telegram-link" href="${escA(settings.telegram_url)}" target="_blank" rel="noopener" aria-label="Diskusi SanzuFreelance di Telegram">Diskusi SanzuFreelance <span aria-hidden="true">↗</span></a>` : `<a class="telegram-link" href="#" onclick="event.preventDefault();showToast('Tautan grup Telegram belum diatur admin.')" aria-label="Diskusi SanzuFreelance di Telegram">Diskusi SanzuFreelance <span aria-hidden="true">↗</span></a>`}</div></div>`;
      $("#btn-send-submit").addEventListener("click", async () => {
        const field = $("#bulk-entries");
        const emails = field.value.split(/[\s,;]+/).map((x) => x.trim()).filter(Boolean);
        const box = $("#entry-error");
        const showErr = (m) => { if (box) { box.textContent = m; box.hidden = !m; } };
        try {
          const r = await api("submit", { method: "POST", body: { room, emails, member_note: $("#review-notes").value } });
          showErr("");
          showToast(`Pengajuan terkirim: ${r.count} alamat (${r.ids.join(", ")}). Menunggu pemeriksaan admin.`);
          field.value = ""; $("#review-notes").value = ""; countItems(field);
          await refreshMe();
        } catch (e) { showErr(e.message); showToast(e.message); }
      });
    } else if (tab === "history") {
      subsCache = (await api("submissions")).submissions;
      const first = subsCache[0];
      page.innerHTML = `<h1 class="wide-title">Riwayat Pengajuan</h1><p class="page-sub">Status dan kategori ditampilkan terpisah agar perubahan pemeriksaan dapat dilacak.</p><div class="panel"><div class="panel-head"><h3>Daftar Pengajuan</h3><span class="badge blue">${subsCache.length} Total</span></div>${rowTableHTML(subsCache)}</div>${first ? `<div class="section-head"><h2>Detail Riwayat Status</h2></div><div class="statuscard"><div class="panel-head"><h3>${escA(first.id)}</h3>${pill(first.stage)}</div><div class="status-timeline"><div class="timeline-dot"></div><div class="timeline-body"><strong>Menunggu pemeriksaan</strong><p>${fmtDate(first.created_at)}</p></div><div class="timeline-line"></div><div></div><div class="timeline-dot"></div><div class="timeline-body"><strong>Klasifikasi ${escA(first.quality)}</strong><p>Oleh admin</p></div><div class="timeline-line"></div><div></div><div class="timeline-dot"></div><div class="timeline-body"><strong>${first.stage === "Diterima" ? "Diterima secara final" : first.stage === "Ditolak" ? "Ditolak secara final" : "Belum diputuskan final"}</strong><p>${first.stage === "Diterima" ? `Penghasilan ${money(first.paid_rate)} ditambahkan ke saldo` : first.stage === "Ditolak" ? "Tidak menambah saldo" : "Menunggu keputusan admin"}</p></div></div></div>` : ""}`;
    }
    else if (tab === "referral") {
      const ref = await api("referral");
      const target = ref.target;
      const approved = Math.min(ref.validSold, target);
      const progress = target > 0 ? Math.round((approved / target) * 100) : 0;
      const claim = ref.claim;
      const statusText = claim && claim.status === "Dibayarkan" ? "Bonus selesai" : claim && claim.status === "Menunggu Konfirmasi" ? "Menunggu konfirmasi" : approved >= target && target > 0 ? "Target tercapai" : ref.enabled ? "Program aktif" : "Program nonaktif";
      const canClaim = ref.enabled && approved >= target && target > 0 && !claim;
      page.innerHTML = `<div class="referral-page">
      <div class="ref-page-title"><div><div class="ref-eyebrow">PROGRAM KOMUNITAS</div><h1>${ico("gift")} Referral Saya</h1><p>Undang teman melalui link pribadi. Setiap anggota hanya memiliki <strong>satu kesempatan bonus</strong>.</p></div><span class="ref-status ${claim && claim.status === "Dibayarkan" ? "achieved" : ref.enabled ? "enabled" : "disabled"}">${statusText}</span></div>
      <section class="ref-banner"><div class="ref-banner-orb">${ico("gift")}</div><div><span class="ref-kicker">BONUS REFERRAL SATU KALI</span><div class="ref-big-money">${money(ref.reward)}</div><p>${approved >= target && target > 0 ? "Target referral sudah tercapai." : `Dapatkan bonus setelah total ${target} stok teman undanganmu dikonfirmasi valid terjual oleh admin.`}</p></div><span class="ref-banner-lines" aria-hidden="true"></span></section>
      ${!ref.enabled ? `<div class="ref-banner-note">${ico("shield")} Program referral sedang dinonaktifkan admin. Kode, progres, dan riwayat tetap tersedia.</div>` : ""}
      <div class="ref-grid"><section class="ref-card ref-code-card"><header class="ref-card-head"><span class="ref-ico violet">${ico("link")}</span><div><h2>Kode &amp; Link Referral</h2><p>Bagikan undangan pribadimu kepada teman.</p></div></header><div class="ref-label">Kode referral</div><div class="ref-copy-row"><strong>${escA(ref.code || "-")}</strong><button id="btn-copy-code" ${!ref.enabled ? "disabled" : ""} aria-label="Salin kode referral">${ico("copy")} <span>Salin</span></button></div><div class="ref-label">Link referral</div><div class="ref-copy-row ref-url-row"><span>${escA(ref.link)}</span><button id="btn-copy-url" ${!ref.enabled ? "disabled" : ""} aria-label="Salin link referral">${ico("copy")} <span>Salin</span></button></div><button class="ref-main-btn" id="btn-share">${ico("external")} Bagikan Undangan</button></section>
      <section class="ref-card ref-telegram-card"><header class="ref-card-head"><span class="ref-ico blue">${ico("users")}</span><div><h2>Komunitas Telegram</h2><p>Ikuti informasi terbaru dari pengelola SanzuFreelance.</p></div></header><div class="ref-telegram-abstract" aria-hidden="true"></div>${settings.telegram_url ? `<a class="ref-telegram-button" href="${escA(settings.telegram_url)}" target="_blank" rel="noopener">${ico("external")} Buka Grup Telegram</a>` : `<button class="ref-telegram-button" disabled>${ico("external")} Tautan Belum Tersedia</button>`}<p class="ref-small-foot">Tautan grup dapat diubah atau dinonaktifkan admin kapan saja.</p></section></div>
      <div class="ref-grid ref-second-grid"><section class="ref-card"><header class="ref-card-head"><span class="ref-ico teal">${ico("chart")}</span><div><h2>Progress Referral</h2><p>Hanya stok teman undangan yang benar-benar valid terjual dan diterima admin yang dihitung.</p></div></header><div class="ref-progress-heading"><strong>${approved}<span> / ${target}</span></strong><span>${progress}% tercapai</span></div><div class="ref-progress-track"><span style="width:${progress}%"></span></div><p class="ref-progress-note">${claim && claim.status === "Dibayarkan" ? "Bonus referral sudah dikonfirmasi." : claim && claim.status === "Menunggu Konfirmasi" ? "Klaim menunggu konfirmasi admin." : approved >= target && target > 0 ? "Target berhasil tercapai." : `Kurang ${Math.max(0, target - approved)} valid terjual lagi dari seluruh anggota undanganmu untuk mendapatkan bonus.`}</p><div class="ref-two-stats"><div><small>Teman diundang</small><b>${ref.subordinates.length}</b></div><div><small>Total valid terjual</small><b>${approved}</b></div></div><div class="ref-contributor-list" style="margin-top:14px;padding-top:12px;border-top:1px solid #4960985c"><strong style="font-size:12px;color:#dce8ff">Rincian valid terjual dari teman undangan</strong>${ref.subordinates.map((w) => `<div style="display:flex;justify-content:space-between;gap:10px;margin-top:9px;font-size:12px;color:#afc3e8"><span>${escA(w.display_name)}</span><b style="color:#eaf5ff">${w.validSold} valid</b></div>`).join("")}</div></section>
      <section class="ref-card ref-reward-card"><header class="ref-card-head"><span class="ref-ico amber">${ico("gift")}</span><div><h2>Status Bonus</h2><p>Bonus satu kali, bukan reward berulang.</p></div></header><div class="ref-reward-value">${money(ref.reward)}</div><div class="ref-reward-status">${claim && claim.status === "Dibayarkan" ? `<span class="ref-ok">${ico("check")} Sudah dikonfirmasi</span>` : claim && claim.status === "Menunggu Konfirmasi" ? `<span class="ref-wait">${ico("clock")} Menunggu konfirmasi admin</span>` : approved >= target && target > 0 ? `<span class="ref-ok">${ico("check")} Target tercapai</span>` : `<span class="ref-wait">${ico("clock")} Belum memenuhi syarat</span>`}</div>${canClaim ? `<button class="ref-claim-btn" id="btn-claim">Ajukan Klaim Bonus</button>` : ""}<p class="ref-small-foot">${claim && claim.status === "Dibayarkan" ? "Bonus telah dikonfirmasi sekali." : "Setelah target tercapai, bonus diproses satu kali setelah dikonfirmasi admin."}</p></section></div>
      <div class="ref-inline-note">${ico("shield")} <span>Program ini berlaku satu kali per anggota. Target dan nominal ditetapkan admin; perubahan tarif tidak mengulang bonus yang sudah selesai.</span></div></div>`;
      const copyVal = async (v, label) => { try { await navigator.clipboard.writeText(v); showToast(`${label} disalin.`); } catch { showToast("Gagal menyalin otomatis — salin manual dari kolom di atas."); } };
      $("#btn-copy-code").addEventListener("click", () => copyVal(ref.code || "", "Kode referral"));
      $("#btn-copy-url").addEventListener("click", () => copyVal(ref.link || "", "Link referral"));
      $("#btn-share").addEventListener("click", async () => {
        if (navigator.share) { try { await navigator.share({ title: "SanzuFreelance", text: "Yuk bergabung di SanzuFreelance!", url: ref.link }); return; } catch {} }
        copyVal(ref.link || "", "Link referral");
      });
      const claimBtn = $("#btn-claim");
      if (claimBtn) claimBtn.addEventListener("click", async () => {
        try { await api("referral-claim", { method: "POST", body: {} }); showToast("Klaim bonus dikirim, menunggu konfirmasi admin."); render(); }
        catch (e) { showToast(e.message); }
      });
    } else if (tab === "profile") {
      notifsCache = (await api("notifications")).notifications;
      const available = ["DANA", "SeaBank"].filter((m) => m === "DANA" ? settings.withdraw_dana : settings.withdraw_seabank);
      const methodOptions = available.includes(me.user.payment_method) ? available : (me.user.payment_method ? [me.user.payment_method, ...available] : available);
      page.innerHTML = `<h1 class="wide-title">Profil &amp; Pembayaran</h1><p class="page-sub">Kelola profil, tujuan penarikan, dan pemberitahuan yang kamu terima.</p><div class="pane-grid">
      <section class="profile-main-card"><div class="profile-info-head"><div class="avatar avatar-default">${ico("user")}</div><div><h3 id="profile-current-name">${escA(me.user.display_name)}</h3><span class="profile-status">${stateLabel()}</span><div class="profile-help" style="margin-top:6px">Bergabung ${fmtDate(me.user.created_at)}</div></div></div><div class="profile-accent"></div>
      <h3 class="profile-section-title">Informasi Profil</h3><p class="profile-section-desc">Nama akun untuk identitas pengajuan dan penarikan.</p><div class="profile-field"><label for="member-display-name">Nama pengguna</label><input class="field" id="member-display-name" value="${escA(me.user.display_name)}" maxlength="100"></div>
      <div class="profile-accent"></div><h3 class="profile-section-title">Tujuan Penarikan</h3><p class="profile-section-desc">Pilih metode yang tersedia dari admin. Nomor akan digunakan saat kamu mengajukan penarikan.</p><div class="profile-method-tags">${["DANA", "SeaBank"].map((m) => `<span>${m} · ${available.includes(m) ? "Tersedia" : "Nonaktif"}</span>`).join("")}</div><div class="profile-field"><label for="member-payment-method">Metode penarikan</label><select class="field" id="member-payment-method">${methodOptions.map((m) => `<option value="${m}" ${me.user.payment_method === m ? "selected" : ""} ${!available.includes(m) ? "disabled" : ""}>${m}${!available.includes(m) ? " (nonaktif)" : ""}</option>`).join("")}</select></div><div id="member-payment-fields"></div><div class="profile-notice">Nomor tersimpan saat ini: <strong style="color:white">${me.user.payment_number ? escA(me.user.payment_number) : "belum diisi"}</strong> (ditampilkan termask). Untuk menyimpan perubahan profil, isi ulang nomor lengkap di bawah ini — server hanya menerima nomor 8–20 digit, bukan nomor termask.</div><button class="btn btn-primary profile-save-btn" id="btn-save-profile">${ico("check")} Simpan Profil &amp; Pembayaran</button></section>
      <section class="profile-notify-card"><h3 class="profile-section-title">Preferensi Notifikasi</h3><p class="profile-section-desc">Notifikasi dalam website aktif untuk semua perubahan dari admin (buka/tutup setoran, mulai diperiksa, perubahan klasifikasi, keputusan akhir).</p><div class="profile-toggle-box"><div><strong>Pemberitahuan dalam website</strong><p>Selalu aktif di versi live ini.</p></div><input aria-label="Pemberitahuan dalam website" type="checkbox" checked disabled></div>
      <div class="profile-accent"></div><h3 class="profile-section-title">Pemberitahuan Terbaru</h3><p class="profile-section-desc">Perubahan status dari admin muncul di sini.</p><div class="profile-inbox" id="profile-notification-list">${inboxHTML(notifsCache)}</div>
      <div class="profile-accent"></div><h3 class="profile-section-title">Penarikan</h3><p class="profile-section-desc">DANA / SeaBank, sesuai metode yang admin aktifkan. Satu permintaan aktif pada satu waktu.</p><button class="btn btn-primary" onclick="withdrawModal()">${ico("wallet")} Ajukan Penarikan</button></section></div>`;
      const renderPayFields = () => {
        const m = $("#member-payment-method").value;
        $("#member-payment-fields").innerHTML = `<div class="profile-field"><label for="member-payment-number">${m === "DANA" ? "Nomor akun DANA" : "Nomor rekening SeaBank"}</label><input class="field" id="member-payment-number" inputmode="numeric" autocomplete="off" placeholder="${m === "DANA" ? "Contoh: 081234567890" : "Masukkan nomor rekening SeaBank"}"></div>${m === "SeaBank" ? `<div class="profile-field"><label for="member-bank-holder">Nama pemilik rekening SeaBank</label><input class="field" id="member-bank-holder" autocomplete="off" placeholder="Nama sesuai rekening" value="${escA(me.user.payment_holder)}"></div>` : ""}`;
      };
      renderPayFields();
      $("#member-payment-method").addEventListener("change", renderPayFields);
      $("#btn-save-profile").addEventListener("click", async () => {
        const m = $("#member-payment-method").value;
        const num = $("#member-payment-number").value.trim();
        if (!num) { showToast("Isi ulang nomor pembayaran lengkap (8–20 digit) untuk menyimpan profil."); return; }
        try {
          const r = await api("update-profile", { method: "POST", body: { display_name: $("#member-display-name").value, payment_method: m, payment_number: num, payment_holder: m === "SeaBank" ? $("#member-bank-holder").value : "" } });
          me.user = r.user;
          showToast("Profil tersimpan.");
          render();
        } catch (e) { showToast(e.message); }
      });
    }
  } catch (e) {
    page.innerHTML = `<div class="error">${escA(e.message)}</div>`;
  }
}

async function boot() {
  const logoEl = $("#auth-logo");
  if (logoEl) logoEl.src = LOGO;
  try {
    settings = (await api("public-settings")).settings;
  } catch (e) {
    $("#auth-view").style.display = "grid";
    $("#auth-msg").innerHTML = `<div class="error">${escA(e.message)}</div>`;
    return;
  }
  try {
    me = await api("me");
    $("#auth-view").style.display = "none";
    $("#app-view").style.display = "flex";
    render();
  } catch {
    $("#auth-view").style.display = "grid";
    $("#app-view").style.display = "none";
    const ref = new URLSearchParams(location.search).get("ref");
    if (ref) { $("#tab-register").click(); $("#reg-ref").value = ref; }
  }
}
$("#tab-login").addEventListener("click", () => {
  $("#tab-login").classList.add("active"); $("#tab-register").classList.remove("active");
  $("#login-form").style.display = "block"; $("#register-form").style.display = "none";
});
$("#tab-register").addEventListener("click", () => {
  $("#tab-register").classList.add("active"); $("#tab-login").classList.remove("active");
  $("#register-form").style.display = "block"; $("#login-form").style.display = "none";
});
$("#login-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  try { await api("login", { method: "POST", body: { email: $("#login-email").value, password: $("#login-password").value } }); boot(); }
  catch (err) { $("#auth-msg").innerHTML = `<div class="error">${escA(err.message)}</div>`; }
});
$("#register-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  try {
    const r = await api("register", { method: "POST", body: { display_name: $("#reg-name").value, email: $("#reg-email").value, password: $("#reg-password").value, referral_code: $("#reg-ref").value } });
    $("#auth-msg").innerHTML = `<div class="okbox">${escA(r.message)}</div>`;
    $("#tab-login").click();
  } catch (err) { $("#auth-msg").innerHTML = `<div class="error">${escA(err.message)}</div>`; }
});
boot();
